SELECT current_database(),current_setting('default_transaction_read_only'),clock_timestamp();
WITH scopes AS (SELECT id,tenant_id,'W'||dense_rank() OVER (ORDER BY id) AS w,'T'||dense_rank() OVER (ORDER BY tenant_id) AS t FROM workspaces)
SELECT s.t,s.w,d.source_type,d.context_type,count(*) AS documents,count(*) FILTER (WHERE coalesce(d.storage_key,'')<>'') AS object_refs,coalesce(sum(d.size_bytes),0) AS declared_bytes,count(*) FILTER (WHERE s.id IS NULL OR s.tenant_id IS NULL) AS missing_scope FROM context_documents d LEFT JOIN scopes s ON s.id=d.workspace_id GROUP BY 1,2,3,4 ORDER BY 1,2,3,4;
SELECT count(*) AS versions,count(*) FILTER (WHERE d.id IS NULL) AS missing_document,count(*) FILTER (WHERE coalesce(v.storage_key,'')<>'') AS object_refs,coalesce(sum(v.size_bytes),0) AS declared_bytes FROM context_document_versions v LEFT JOIN context_documents d ON d.id=v.document_id;
WITH scopes AS (SELECT id,tenant_id,'W'||dense_rank() OVER (ORDER BY id) AS w,'T'||dense_rank() OVER (ORDER BY tenant_id) AS t FROM workspaces), jobs AS (SELECT *,CASE WHEN result IS JSON THEN result::jsonb ELSE '{}'::jsonb END AS r FROM job_queue)
SELECT s.t,s.w,j.type,j.status,count(*) AS jobs,count(*) FILTER (WHERE coalesce(r->>'storageKey','')<>'') AS object_refs,count(*) FILTER (WHERE coalesce(r->>'contentBase64','')<>'') AS inline_base64,count(*) FILTER (WHERE result IS NOT NULL AND NOT result IS JSON) AS invalid_json,count(*) FILTER (WHERE s.id IS NULL OR s.tenant_id IS NULL) AS missing_scope FROM jobs j LEFT JOIN scopes s ON s.id=j.workspace_id GROUP BY 1,2,3,4 ORDER BY 1,2,3,4;
SELECT count(*) AS messages,count(*) FILTER (WHERE attachments IS NOT NULL AND attachments<>'[]'::jsonb) AS with_attachments,count(*) FILTER (WHERE content LIKE '%storageKey%') AS content_storage_marker,count(*) FILTER (WHERE tool_calls::text LIKE '%storageKey%') AS tool_storage_marker,count(*) FILTER (WHERE role='tool') AS tool_results FROM chat_messages;
SELECT count(*) AS workspaces,count(*) FILTER (WHERE tenant_id IS NULL) AS missing_tenant,count(*) FILTER (WHERE owner_user_id IS NULL) AS missing_owner FROM workspaces;
